import React, { useState } from "react";

export default function AdminDashboard({ reports, token, setMsg }) {
  const [ngos, setNgos] = useState(null);
  const [events, setEvents] = useState(null);
  const [eventStats, setEventStats] = useState(null);
  const [topStats, setTopStats] = useState(null);

  const API = process.env.REACT_APP_API || "http://localhost:4000";

  const loadData = async (endpoint, setter, field, errMsg) => {
    if (!token) return setMsg("Login as admin first");
    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error(errMsg);
      const data = await res.json();

      setter(data[field] || []);
    } catch (e) {
      console.error(e);
      setMsg(e.message || errMsg);
    }
  };

  const loadTopPerformers = async () => {
    if (!token) return setMsg("Login as admin first");

    try {
      const res = await fetch(`${API}/api/actions/top-performers`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error("Failed to load top performers");

      const data = await res.json();
      setTopStats(data.top);
    } catch (e) {
      console.error(e);
      setMsg(e.message);
    }
  };

  const deleteNgo = async (id) => {
    if (!token) return setMsg("Login as admin first");

    if (!window.confirm("Are you sure you want to remove this NGO?")) return;

    try {
      const res = await fetch(`${API}/api/actions/remove-ngo/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error("Failed to delete NGO");

      setMsg("NGO removed successfully");
      setNgos((prev) => prev.filter((n) => n.id !== id));
    } catch (e) {
      console.error(e);
      setMsg(e.message);
    }
  };

  return (
    <div className="panel">

      {/* ===================== REPORT CARDS ===================== */}
      <div className="admin-section">
        <h3>Admin Reports</h3>

        <div className="cards">
          <div className="stat-card">
            <div className="stat-num">
              {reports?.donations
                ? reports.donations.reduce((s, d) => s + parseFloat(d.amount || 0), 0)
                : "-"}
            </div>
            <div className="stat-label">Total Donation Amount (₹)</div>
          </div>

          <div className="stat-card">
            <div className="stat-num">{reports?.volunteers?.length || 0}</div>
            <div className="stat-label">Total Volunteers</div>
          </div>

          <div className="stat-card">
            <div className="stat-num">{reports?.feedbacks?.length || 0}</div>
            <div className="stat-label">Feedbacks</div>
          </div>
        </div>
      </div>

      {/* ===================== ACTION BUTTONS ===================== */}
      <div className="admin-section">
        <h3>Actions</h3>

        <button
          onClick={() =>
            loadData("/api/actions/ngos", setNgos, "ngos", "Failed to load NGOs")
          }
        >
          View Registered NGOs
        </button>

        <button
          style={{ marginLeft: 8 }}
          onClick={() =>
            loadData(
              "/api/actions/registered-events",
              setEvents,
              "events",
              "Failed to load events"
            )
          }
        >
          View Registered Events
        </button>

        <button
          style={{ marginLeft: 8 }}
          onClick={() =>
            loadData(
              "/api/actions/event-stats",
              setEventStats,
              "events",
              "Failed to load event stats"
            )
          }
        >
          View Event Stats
        </button>

        <button
          style={{ marginLeft: 8 }}
          onClick={loadTopPerformers}
        >
          View Top Performers
        </button>
      </div>

      {/* ===================== TOP PERFORMERS ===================== */}
      {topStats && (
        <div className="admin-section">
          <h3>Top Performers</h3>

          <div className="cards" style={{ display: "grid", gap: 12 }}>
            <div className="stat-card">
              <strong>Most Volunteers Today</strong>
              <div>{topStats.todayMostVolunteers?.title || "No data"}</div>
              <div>Volunteers: {topStats.todayMostVolunteers?.count || 0}</div>
            </div>

            <div className="stat-card">
              <strong>Most Donations Today</strong>
              <div>{topStats.todayMostDonations?.title || "No data"}</div>
              <div>₹{topStats.todayMostDonations?.amount || 0}</div>
            </div>

            <div className="stat-card">
              <strong>Most Volunteers This Week</strong>
              <div>{topStats.weekMostVolunteers?.title || "No data"}</div>
              <div>Volunteers: {topStats.weekMostVolunteers?.count || 0}</div>
            </div>

            <div className="stat-card">
              <strong>Most Donations This Week</strong>
              <div>{topStats.weekMostDonations?.title || "No data"}</div>
              <div>₹{topStats.weekMostDonations?.amount || 0}</div>
            </div>
          </div>
        </div>
      )}

      {/* ===================== EVENTS SECTION ===================== */}
      {events && (
        <div className="admin-section">
          <h3>Registered Events</h3>
          {events.length ? (
            events.map((e) => (
              <div
                key={e.id}
                className="list-card"
              >
                <strong>{e.title}</strong>
                <div style={{ fontSize: 13, color: "#666" }}>{e.date}</div>
              </div>
            ))
          ) : (
            <p>No events registered.</p>
          )}
        </div>
      )}

      {/* ===================== EVENT STATS SECTION ===================== */}
      {eventStats && (
        <div className="admin-section">
          <h3>Event Statistics</h3>
          {eventStats.length ? (
            eventStats.map((ev) => (
              <div key={ev.id} className="list-card" style={{ display: "flex" }}>
                <img
                  src={ev.image_url || "https://via.placeholder.com/120x80"}
                  alt="ev"
                  style={{ width: 100, height: 64, objectFit: "cover", borderRadius: 6 }}
                />
                <div style={{ flex: 1, marginLeft: 12 }}>
                  <div style={{ fontWeight: 600 }}>{ev.title}</div>
                  <div style={{ fontSize: 13, color: "#666" }}>
                    Volunteers: {ev.volunteers_count} — Donations: ₹{ev.donations_sum}
                  </div>
                </div>
              </div>
            ))
          ) : (
            <p>No event statistics loaded.</p>
          )}
        </div>
      )}

      {/* ===================== NGO SECTION ===================== */}
      {ngos && (
        <div className="admin-section">
          <h3>Registered NGOs</h3>
          {ngos.length ? (
            ngos.map((n) => (
              <div key={n.id} className="list-card" style={{ display: "flex", justifyContent: "space-between" }}>
                <div>
                  <strong>{n.name}</strong>
                  <div style={{ fontSize: 13, color: "#666" }}>{n.email}</div>
                </div>

                <button
                  style={{
                    padding: "6px 12px",
                    background: "red",
                    color: "white",
                    border: "none",
                    borderRadius: 6,
                    cursor: "pointer",
                  }}
                  onClick={() => deleteNgo(n.id)}
                >
                  Remove
                </button>
              </div>
            ))
          ) : (
            <p>No NGOs registered.</p>
          )}
        </div>
      )}
    </div>
  );
}
